package com.studyspace.security;
import java.io.IOException; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class AuthFilter extends OncePerRequestFilter { private final JwtService jwt; public AuthFilter(JwtService jwt){this.jwt=jwt;}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException,IOException { String h=req.getHeader("Authorization"); if(h!=null && h.startsWith("Bearer ")) { String id=jwt.validateAndGetUser(h.substring(7)); if(id!=null) req.setAttribute("userId",id); } chain.doFilter(req,res); } }
